class BackendServiceIAPOAuth2ClientInfo {
  /// Application name to be used in OAuth consent screen.
  final String? applicationName;

  /// Name of the client to be generated. Optional - If not provided, the name will be autogenerated by the backend.
  final String? clientName;

  /// Developer's information to be used in OAuth consent screen.
  final String? developerEmailAddress;

  /// Creates a new [BackendServiceIAPOAuth2ClientInfo].
  /// [applicationName] Application name to be used in OAuth consent screen.
  /// [clientName] Name of the client to be generated. Optional - If not provided, the name will be autogenerated by the backend.
  /// [developerEmailAddress] Developer's information to be used in OAuth consent screen.
  BackendServiceIAPOAuth2ClientInfo({
    this.applicationName,
    this.clientName,
    this.developerEmailAddress,
  });

  Map<String, dynamic> toMap() {
    final map = <String, dynamic>{};
    final applicationNameValue = applicationName;
    if (applicationNameValue != null) {
      map['applicationName'] = applicationNameValue;
    }
    final clientNameValue = clientName;
    if (clientNameValue != null) {
      map['clientName'] = clientNameValue;
    }
    final developerEmailAddressValue = developerEmailAddress;
    if (developerEmailAddressValue != null) {
      map['developerEmailAddress'] = developerEmailAddressValue;
    }
    return map;
  }

  factory BackendServiceIAPOAuth2ClientInfo.fromMap(Map<String, dynamic> map) {
    return BackendServiceIAPOAuth2ClientInfo(
      applicationName: map['applicationName'] == null
          ? null
          : map['applicationName'] as String,
      clientName:
          map['clientName'] == null ? null : map['clientName'] as String,
      developerEmailAddress: map['developerEmailAddress'] == null
          ? null
          : map['developerEmailAddress'] as String,
    );
  }
}
